import React from 'react';
import {
    View,
    Text,
    TouchableOpacity,
    ActivityIndicator
} from 'react-native';

import { ParamListBase, useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';

import { useContexState } from '../../hooks/context';
import { styles } from './styles';

import api from '../../services/api';

type YourNavigatorProps = NativeStackNavigationProp<ParamListBase, keyof ParamListBase>

interface CardsProps {
    position: number,
    listItemProps: {
        data: { firstCard: number, id: string };
        list?: {
            [key: string]: [{
                id: number;
                name: string;
                phone: string;
                price: number;
            }]
        };
    };
};

export function Cards({ listItemProps, position }: CardsProps) {
    const cardNumber = listItemProps.data.firstCard + position;
    const randomText = Math.random().toString(36).substr(2, 5);

    const {
        isMountedApi,
        shoppingCartItem,
    } = useContexState();

    const {
        setKeyboardActive,
        setSelectedNumber,
        setAlertActive,
        setPaymentMenuActive,
    } = useContexState();

    const tempShoppingCartItem = [...shoppingCartItem];
    const index = tempShoppingCartItem.indexOf(cardNumber);

    const navigation = useNavigation<YourNavigatorProps>();

    function cardPost() {
        api.post("register", {
            number: cardNumber,
            name: randomText,
            phone: '(00)000000000',
        }).then((response) => {
            // setKeyboardActive(true)
            navigation.navigate('Checkout');
        });
    };

    function colorSelect() {
        if (shoppingCartItem[index]) return { backgroundColor: '#7B68EE' }

        if (listItemProps.list?.[String(cardNumber)]) {
            return {
                backgroundColor: listItemProps.list?.
                [cardNumber][0].price !== 0 ? '#26A744' : '#17A2B7'
            }
        } else return {
            backgroundColor: '#fff',
            color: '#121212'
        }
    };

    function ButtonCard() {
        if (cardNumber <= 9999 && cardNumber >= 0) {
            return (<TouchableOpacity onPress={() => {
                setSelectedNumber(cardNumber);

                if (!listItemProps.list?.[String(cardNumber)] && !shoppingCartItem[index]) {
                    setPaymentMenuActive(true);
                } else {
                    setAlertActive(true);
                }
            }}>
                <View>
                    <Text style={[styles.listText, colorSelect()
                    ]}>
                        {(`0000${cardNumber}`).slice(-4)}
                    </Text>
                </View>
            </TouchableOpacity>)
        } else return <View />
    }

    function LoadIndicator() {
        return (<View style={styles.load}>
            <Text style={{ fontSize: 19, color: 'rgba(0,0,0,0.0)' }}>0000</Text>
            <ActivityIndicator style={{ position: 'absolute' }} size={27} color='#121212' />
        </View >)
    }

    return (isMountedApi ? <ButtonCard /> : <LoadIndicator />);
};
